def build_agent(sandbox):
    # Base beam (welded to glass) with low density
    base = sandbox.add_beam(x=6.0, y=2.06, width=0.5, height=0.1, density=0.5)
    if hasattr(sandbox, 'weld_to_glass'):
        sandbox.weld_to_glass(base, (6.0, 2.0))

    # Wiper beam: long, thin, low density to meet mass budget
    wiper = sandbox.add_beam(x=6.0, y=2.11, width=0.05, height=0.05, angle=0, density=0.1)

    # Pivot joint connecting base to wiper
    pivot = sandbox.add_joint(
        base, wiper, (6.0, 2.11), type='pivot',
        lower_limit=-1.3, upper_limit=1.3
    )

    return {"body": base, "motors": [pivot]}

def agent_action(sandbox, agent_body, step_count):
    motors = agent_body.get("motors", []) if isinstance(agent_body, dict) else []
    if not motors:
        return

    # Ensure all bodies are awake
    if hasattr(sandbox, 'set_awake'):
        for body in sandbox.bodies:
            sandbox.set_awake(body, True)

    # Continuous sweeping motion with torque-limited motor
    period = 300
    half = (step_count // period) % 2
    motor_speed = 10.0 if half == 0 else -10.0
    sandbox.set_motor(motors[0], motor_speed, max_torque=10.0)
